import React, { useEffect, useState } from "react";
import axios from "axios";
import { FaBook, FaChartLine } from "react-icons/fa";
import AlertBox from "./AlertBox";

function StudentDashboard() {
  const userId = localStorage.getItem("user_id");
  const userName = localStorage.getItem("user_name");

  const [courses, setCourses] = useState([]);
  const [progress, setProgress] = useState({});
  const [alert, setAlert] = useState(null);

  // fetch enrolled courses
  const fetchCourses = async () => {
    try {
      const res = await axios.get("http://127.0.0.1:8000/courses");
      const allCourses = res.data.courses || [];

      // filter enrolled courses
      const enrollRes = await axios.get(
        `http://127.0.0.1:8000/enrollments/${userId}`
      );

      const enrolledIds = enrollRes.data.map((e) => e.course_id);

      const myCourses = allCourses.filter((c) =>
        enrolledIds.includes(c.id)
      );

      setCourses(myCourses);
    } catch (err) {
      console.error(err);
    }
  };

useEffect(() => {
  const fetchCourses = async () => {
    try {
      const res = await axios.get("http://127.0.0.1:8000/courses");
      const allCourses = res.data.courses || [];

      const enrollRes = await axios.get(
        `http://127.0.0.1:8000/enrollments/${userId}`
      );

      const enrolledIds = enrollRes.data.map((e) => e.course_id);

      const myCourses = allCourses.filter((c) =>
        enrolledIds.includes(c.id)
      );

      setCourses(myCourses);
    } catch (err) {
      console.error(err);
    }
  };

  fetchCourses();
}, [userId]);

  // update progress
  const handleProgress = async (courseId, value) => {
    try {
      const response = await axios.post(
        "http://127.0.0.1:8000/update-progress",
        {
          user_id: parseInt(userId),
          course_id: courseId,
          completed_topics: parseInt(value)
        }
      );

      setAlert({
        message: response.data.message,
        type: "success"
      });

      setProgress({
        ...progress,
        [courseId]: value
      });
    } catch (err) {
      console.error(err);
      setAlert({
        message: "Failed to update progress",
        type: "error"
      });
    }
  };

  return (
    <div>
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <h2 style={{ color: "#4a148c", marginBottom: "10px" }}>
        Student Dashboard
      </h2>

      <p style={{ marginBottom: "20px" }}>
        Welcome, <strong>{userName}</strong>
      </p>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))",
          gap: "20px"
        }}
      >
        {courses.map((course) => {
          const currentProgress = progress[course.id] || 0;
          const percentage = (currentProgress / 10) * 100;

          return (
            <div
              key={course.id}
              style={{
                background: "#fff",
                borderRadius: "16px",
                padding: "20px",
                boxShadow: "0 6px 18px rgba(0,0,0,0.08)"
              }}
            >
              <div style={{ fontSize: "26px", color: "#7b1fa2" }}>
                <FaBook />
              </div>

              <h3 style={{ margin: "10px 0" }}>{course.title}</h3>
              <p>{course.description}</p>

              <p>
                <strong>Subject Code:</strong> {course.subject_code}
              </p>

              {/* Progress Bar */}
              <div
                style={{
                  height: "10px",
                  background: "#eee",
                  borderRadius: "10px",
                  margin: "10px 0"
                }}
              >
                <div
                  style={{
                    width: `${percentage}%`,
                    height: "100%",
                    background: "#7b1fa2",
                    borderRadius: "10px"
                  }}
                ></div>
              </div>

              <p style={{ fontSize: "13px" }}>
                Progress: {percentage}%
              </p>

              {/* Input */}
              <input
                type="number"
                placeholder="Completed topics (0-10)"
                onChange={(e) =>
                  setProgress({
                    ...progress,
                    [course.id]: e.target.value
                  })
                }
                style={{
                  width: "100%",
                  padding: "8px",
                  borderRadius: "8px",
                  border: "1px solid #ccc",
                  marginTop: "8px"
                }}
              />

              <button
                onClick={() =>
                  handleProgress(course.id, progress[course.id] || 0)
                }
                style={{
                  marginTop: "10px",
                  width: "100%",
                  background: "#7b1fa2",
                  color: "#fff",
                  border: "none",
                  padding: "10px",
                  borderRadius: "8px",
                  cursor: "pointer"
                }}
              >
                <FaChartLine /> Update Progress
              </button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default StudentDashboard;
